True def transform(grid):
    out = [row[:] for row in grid]
    anchors = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5]
    if len(anchors) < 2:
        return out
    h, w = len(grid), len(grid[0])
    def neighbor_count(pos):
        r, c = pos
        return sum(1 for rr in range(max(0, r-2), min(h, r+3))
                   for cc in range(max(0, c-3), min(w, c+4))
                   if (rr, cc) != pos and grid[rr][cc] != 0)
    source = max(anchors, key=neighbor_count)
    target = next(p for p in anchors if p != source)
    sr, sc = source
    tr, tc = target
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value and (r, c) != source:
                rr, cc = tr + r - sr, tc + c - sc
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = value
    out[tr][tc] = 0
    return out
